// a message is noticed while another tab is in front. Sleeper already counts what needs attention in
// its sidebar ("Direct Messages": unread DMs, DM requests, friend requests; kept current over its
// own socket); this only mirrors that number. Reads the page, sends nothing, changes nothing else.
(() => {
  // Pure: Sleeper's badge text → count, and a title with our "(n) " prefix set, replaced or removed.
  function readCount(text) {
    const count = parseInt(String(text ?? '').trim(), 10);
    return Number.isFinite(count) && count > 0 ? count : 0;
  }
  function titleWith(title, count) {
    const base = String(title ?? '').replace(/^\(\d+\+?\) /, '');
    return count > 0 ? `(${count > 99 ? '99+' : count}) ${base}` : base;
  }
  globalThis.__catnapperNotify = { readCount, titleWith };
  if (typeof document === 'undefined') return;

  const INDICATOR = '.nav-private-messages-item .nav-notification-indicator';
  let shown = null, originalIcon = null, dotIcon = null;
  const iconLink = () => document.querySelector('link[rel~="icon"]');
  // The favicon with a red dot, drawn once. If the image cannot be read (no CORS), a plain tile is used.
  function drawDot(image) {
    const canvas = document.createElement('canvas'); canvas.width = canvas.height = 32;
    const pen = canvas.getContext('2d');
    if (image) pen.drawImage(image, 0, 0, 32, 32); else { pen.fillStyle = '#18202f'; pen.fillRect(0, 0, 32, 32); }
    pen.beginPath(); pen.arc(23, 9, 8, 0, Math.PI * 2); pen.fillStyle = '#ff2b6d'; pen.fill();
    pen.lineWidth = 2; pen.strokeStyle = '#fff'; pen.stroke();
